draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // draw self compassion symbol (two hands holding heart)
  ctx.beginPath();
  ctx.moveTo(W/2 - 40 + 20 * Math.sin(t), H/2 - 30);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 40 - 20 * Math.sin(t), H/2 - 30);
  ctx.lineTo(W/2 + 20 - 10 * Math.sin(t), H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
